```

`l3vpn.j2`:

```jinja2
{% if ansible_network_os == 'cisco.ios.ios' %}
router bgp {{ asn }}
  address-family vpnv4
    neighbor {{ peer_ip }} activate
{% elif ansible_network_os == 'cisco.ios.iosxe' %}
router bgp {{ asn }}
  address-family vpnv4
    neighbor {{ peer_ip }} activate
{% elif ansible_network_os == 'juniper.junos.junos' %}
protocols {
